insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-01','AKIDAH','sederhana','Apakah maksud akidah?','Amalan harian','Pegangan dan kepercayaan','Peraturan hidup','Ibadah khusus','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-02','AKIDAH','sederhana','Antara berikut, yang manakah termasuk dalam rukun iman?','Solat lima waktu','Percaya kepada malaikat','Berpuasa','Menunaikan haji','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-03','AKIDAH','sederhana','Beriman kepada Allah bermaksud…','Mengetahui kewujudan-Nya sahaja','Meyakini dan mentaatinya','Menyebut nama-Nya','Menghafal sifat-Nya','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-04','AKIDAH','sederhana','Apakah maksud beriman kepada malaikat?','Menganggap malaikat seperti manusia','Percaya malaikat makhluk Allah yang taat','Menyembah malaikat','Menghafal nama malaikat sahaja','B');
