insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-06','AKIDAH','sederhana','Apakah tugas malaikat Jibril?','Menurunkan hujan','Menyampaikan wahyu','Mencabut nyawa','Menulis amalan','B');
