insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-10','AKIDAH','sederhana','Rasul mempunyai sifat…','Suka berdusta','Amanah','Pelupa','Lalai','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-11','AKIDAH','sederhana','Apakah maksud beriman kepada hari kiamat?','Mengetahui bila berlaku','Percaya ia pasti berlaku','Mengira tarikhnya','Melihat tanda sahaja','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-12','AKIDAH','sederhana','Apakah maksud qada’?','Ketentuan Allah sejak azali','Kejadian manusia','Amalan manusia','Kehidupan dunia','A');
