insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-14','AKIDAH','sederhana','Antara berikut, yang manakah sifat wajib bagi Allah?','Lemah','Berkuasa','Mengantuk','Lupa','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-15','AKIDAH','sederhana','Apakah maksud Allah Maha Mendengar?','Mendengar sebahagian','Mendengar semua tanpa alat','Mendengar dengan telinga','Mendengar suara kuat sahaja','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-16','AKIDAH','sederhana','Apakah maksud Allah Maha Melihat?','Melihat waktu siang sahaja','Melihat semua tanpa batas','Melihat dengan mata','Melihat benda besar sahaja','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-17','AKIDAH','sederhana','Rasul dipilih daripada kalangan…','Malaikat','Jin','Manusia','Haiwan','C');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-18','AKIDAH','sederhana','Bilangan rukun iman ialah…','4','5','6','7','C');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-19','AKIDAH','sederhana','Apakah maksud kufur?','Percaya sepenuhnya','Tidak percaya kepada Allah','Menghafal Al-Quran','Mengamalkan ibadah','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-20','AKIDAH','sederhana','Apakah maksud syirik?','Menyembah Allah','Menyekutukan Allah','Mengingati Allah','Mentaati Allah','B');
