insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-22','AKIDAH','sederhana','Apakah maksud iman?','Percaya di mulut sahaja','Percaya dengan hati, lisan dan amal','Menghafal sahaja','Menulis sahaja','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-23','AKIDAH','sederhana','Apakah kesan beriman kepada Allah?','Menjadi sombong','Tenang dan taat','Lalai','Takut manusia','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-24','AKIDAH','sederhana','Apakah maksud nabi?','Pembawa kitab sahaja','Manusia pilihan Allah','Malaikat','Jin','B');
