insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-27','AKIDAH','tinggi','Jika seseorang percaya kepada bomoh lebih daripada Allah, ini menunjukkan…','Iman kuat','Syirik','Bijak','Berani','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-28','AKIDAH','tinggi','Mengapakah malaikat tidak pernah derhaka kepada Allah?','Mereka tiada nafsu','Mereka manusia','Mereka bebas','Mereka kuat','A');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-29','AKIDAH','tinggi','Apakah hikmah beriman kepada hari kiamat?','Takut tanpa sebab','Mendorong berbuat baik','Menjadi malas','Tidak peduli','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-30','AKIDAH','tinggi','Apakah kesan tidak percaya kepada qada’ dan qadar?','Redha','Mudah putus asa','Tenang','Sabar','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-31','AKIDAH','tinggi','Mengapakah rasul diutuskan kepada manusia?','Untuk hiburan','Memberi petunjuk','Untuk kekayaan','Untuk kuasa','B');
