insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-33','AKIDAH','tinggi','Jika seseorang hanya percaya sebahagian rukun iman…','Iman sempurna','Iman tidak lengkap','Lebih baik','Tidak penting','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-34','AKIDAH','tinggi','Apakah kesan memahami sifat Allah?','Takut tanpa sebab','Lebih mengenal dan taat','Menjadi sombong','Tidak berubah','B');
