insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-37','AKIDAH','tinggi','Jika seseorang diuji, apakah kaitannya dengan qada’ dan qadar?','Tiada kaitan','Ketentuan Allah','Salah manusia sahaja','Nasib semata-mata','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-38','AKIDAH','tinggi','Apakah sikap terbaik apabila ditimpa musibah?','Marah','Redha dan sabar','Menyalahkan orang','Putus asa','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-39','AKIDAH','tinggi','Mengapakah penting beriman kepada kitab?','Untuk hafal','Sebagai panduan hidup','Untuk simpan','Untuk cerita','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-40','AKIDAH','tinggi','Jika seseorang tidak percaya rasul, apakah kesannya?','Iman lengkap','Iman terbatal','Lebih baik','Tiada kesan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-41','AKIDAH','tinggi','Apakah tanda orang beriman kepada Allah?','Sombong','Taat perintah-Nya','Lalai','Takut manusia','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-42','AKIDAH','tinggi','Mengapakah iman perlu dijaga?','Supaya terkenal','Mudah terjejas','Supaya kaya','Supaya kuat','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-43','AKIDAH','tinggi','Apakah kesan syirik dalam kehidupan?','Tenang','Rosak akidah','Bahagia','Berjaya','B');
