insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-47','AKIDAH','tinggi','Apakah kesan meninggalkan ajaran akidah?','Tiada apa','Sesat','Bijak','Kuat','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-48','AKIDAH','tinggi','Bagaimanakah cara terbaik mempelajari akidah?','Dengar sahaja','Belajar dan faham','Hafal sahaja','Abaikan','B');
