insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('AKIDAH-50','AKIDAH','tinggi','Apakah kesimpulan tentang akidah?','Tidak penting','Asas keimanan','Sekadar ilmu','Hanya teori','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-01','ALQURAN','sederhana','Mengapakah Al-Quran diturunkan secara berperingkat?','Supaya mudah difahami dan diamalkan','Supaya cepat dihafal','Supaya pendek','Supaya mudah ditulis','A');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-02','ALQURAN','sederhana','Apakah kepentingan mempelajari tajwid ketika membaca Al-Quran?','Supaya suara lebih kuat','Supaya bacaan lebih tepat dan betul','Supaya cepat habis','Supaya orang kagum','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-03','ALQURAN','sederhana','Mengapakah Surah Al-Fatihah wajib dibaca dalam solat?','Kerana surah paling pendek','Kerana rukun solat','Kerana mudah dihafal','Kerana selalu dibaca','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-04','ALQURAN','sederhana','Apakah pengajaran utama daripada kisah Nabi Yusuf dalam Al-Quran?','Kepentingan kekayaan','Kesabaran dan kejujuran','Keberanian berperang','Kepintaran berniaga','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-05','ALQURAN','sederhana','Mengapakah kita digalakkan bertadabbur Al-Quran?','Untuk menghafal lebih cepat','Untuk memahami dan menghayati makna','Untuk membaca dengan kuat','Untuk menunjuk-nunjuk','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-06','ALQURAN','sederhana','Apakah kesan membaca Al-Quran dengan betul dalam kehidupan harian?','Menjadi lebih sombong','Mendapat ketenangan hati','Menjadi terkenal','Mendapat kekayaan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-07','ALQURAN','sederhana','Mengapakah Al-Quran diturunkan dalam bahasa Arab?','Bahasa paling lama','Bahasa Nabi Muhammad dan kaumnya','Bahasa paling mudah','Bahasa semua manusia','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-08','ALQURAN','sederhana','Apakah hikmah surah Makkiyah lebih menekankan akidah?','Supaya cepat hafal','Untuk menguatkan keimanan','Untuk belajar hukum','Untuk belajar sejarah','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-09','ALQURAN','sederhana','Mengapakah Surah Al-Baqarah digalakkan dibaca di rumah?','Supaya rumah besar','Untuk menghalau syaitan','Untuk menambah rezeki sahaja','Untuk cepat tidur','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-10','ALQURAN','sederhana','Apakah tindakan terbaik jika tidak memahami ayat Al-Quran?','Abaikan','Rujuk guru atau tafsir','Tukar ayat','Hentikan bacaan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-11','ALQURAN','sederhana','Mengapakah menjaga adab membaca Al-Quran penting?','Supaya nampak pandai','Untuk menghormati kitab suci','Supaya cepat habis','Supaya orang puji','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-12','ALQURAN','sederhana','Apakah kesan menghafal Al-Quran sejak kecil?','Mudah lupa','Membentuk disiplin dan ingatan kuat','Menjadi malas','Tidak perlu belajar lain','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-13','ALQURAN','sederhana','Mengapakah ayat Kursi sering dibaca sebelum tidur?','Untuk cepat tidur','Sebagai perlindungan diri','Untuk mimpi indah','Untuk hafal sahaja','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-14','ALQURAN','sederhana','Apakah kaitan Al-Quran dengan akhlak seorang Muslim?','Tiada kaitan','Membentuk akhlak mulia','Hanya untuk ibadah','Hanya untuk hafalan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-15','ALQURAN','sederhana','Mengapakah kita perlu berwuduk ketika memegang mushaf?','Supaya cepat hafal','Untuk menjaga kesucian','Supaya tidak koyak','Supaya ringan','B');
