insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-17','ALQURAN','sederhana','Mengapakah penting membezakan surah Makkiyah dan Madaniyah?','Untuk hafalan','Untuk memahami konteks ayat','Untuk pertandingan','Untuk menulis','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-18','ALQURAN','sederhana','Apakah kesan membaca Al-Quran tanpa tajwid?','Lebih cepat','Boleh mengubah makna','Lebih sedap','Tiada kesan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-19','ALQURAN','sederhana','Apakah hikmah kisah Ashabul Kahfi?','Kepentingan tidur','Keimanan dan perlindungan Allah','Kepentingan masa','Kepintaran','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-20','ALQURAN','sederhana','Mengapakah umat Islam digalakkan membaca Al-Quran setiap hari?','Supaya cepat habis','Untuk mendapat pahala dan petunjuk','Supaya terkenal','Supaya dipuji','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-21','ALQURAN','sederhana','Apakah fungsi utama Al-Quran dalam kehidupan manusia?','Buku sejarah','Petunjuk hidup','Buku cerita','Buku latihan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-22','ALQURAN','sederhana','Mengapakah kita perlu menghormati orang yang membaca Al-Quran?','Supaya dipuji','Kerana membaca kalam Allah','Supaya senyap','Supaya cepat habis','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-23','ALQURAN','sederhana','Apakah kepentingan memahami maksud ayat Al-Quran?','Supaya cepat hafal','Supaya boleh diamalkan','Supaya pandai bercakap','Supaya nampak hebat','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-24','ALQURAN','sederhana','Apakah sikap terbaik ketika mendengar bacaan Al-Quran?','Bercakap','Mendengar dengan khusyuk','Bermain','Tidur','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-25','ALQURAN','sederhana','Mengapakah Al-Quran sesuai sepanjang zaman?','Kerana pendek','Kandungannya lengkap dan relevan','Kerana bahasa Arab','Kerana mudah','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-26','ALQURAN','tinggi','Seorang murid membaca Al-Quran tanpa tajwid. Apakah kesan paling tepat?','Tiada kesan','Boleh menukar maksud ayat','Lebih cepat','Lebih mudah','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-27','ALQURAN','tinggi','Jika seseorang hanya membaca tanpa memahami, apakah yang kurang?','Suara','Penghayatan','Hafalan','Masa','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-28','ALQURAN','tinggi','Apakah tindakan terbaik jika rakan tidak menghormati Al-Quran?','Biarkan','Tegur dengan baik','Marah kuat','Jauhkan diri','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-29','ALQURAN','tinggi','Seorang pelajar ingin menjadi hafiz. Apakah amalan paling penting?','Bermain','Konsisten menghafal dan ulang','Tidur','Menonton TV','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-30','ALQURAN','tinggi','Mengapakah kisah dalam Al-Quran diulang dalam beberapa surah?','Supaya panjang','Untuk penegasan dan pengajaran','Untuk hafalan','Untuk hiasan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-31','ALQURAN','tinggi','Bagaimanakah Al-Quran membentuk masyarakat yang baik?','Dengan cerita sahaja','Dengan memberi panduan hidup','Dengan hukuman sahaja','Dengan hafalan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-32','ALQURAN','tinggi','Jika seseorang mengamalkan ajaran Al-Quran, apakah kesannya?','Hidup teratur','Menjadi malas','Menjadi sombong','Menjadi lemah','A');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ALQURAN-33','ALQURAN','tinggi','Mengapakah penting membaca Al-Quran dengan istiqamah?','Supaya cepat habis','Untuk membina hubungan dengan Allah','Supaya terkenal','Supaya pandai sahaja','B');
