insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('IBADAH-01','IBADAH','sederhana','Ali sibuk bermain hingga hampir habis waktu solat. Apakah tindakan terbaik?','Selesaikan permainan dahulu supaya tidak terganggu','Berhenti apabila hampir tamat waktu','Segera berhenti dan menunaikan solat','Tunggu kawan selesai bermain','C');
