insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('IBADAH-03','IBADAH','sederhana','Ahmad terlupa solat Zohor. Apa perlu dilakukan?','Solat pada waktu yang sama hari berikutnya','Qada sebaik sahaja teringat','Menunggu waktu Asar','Menggantikan dengan doa sahaja','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('IBADAH-04','IBADAH','sederhana','Cara terbaik menunjukkan syukur ialah:','Mengingati nikmat sahaja','Menggunakan nikmat dengan betul','Berkongsi apabila perlu','Mengucap syukur tanpa tindakan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('IBADAH-05','IBADAH','sederhana','Puasa melatih kesabaran kerana:','Mengurangkan aktiviti fizikal','Menahan kehendak diri secara sedar','Mengubah rutin harian','Mengelakkan makanan','B');
insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('IBADAH-06','IBADAH','sederhana','Cara paling berkesan ingat waktu solat:','Mengikut kebiasaan waktu harian','Menunggu orang lain mengingatkan','Menggunakan alarm atau jadual','Bergantung kepada azan sahaja','C');
