insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ADAB-01','ADAB','sederhana','Ali lewat masuk kelas kerana bermain. Apakah adab yang sepatutnya dilakukan?','Masuk tanpa minta izin','Menunggu di luar kelas','Meminta maaf dan minta izin masuk','Duduk di belakang sahaja','C');
