insert into soalan (id,topik,aras,soalan,a,b,c,d,jawapan) values ('ADAB-03','ADAB','sederhana','Jika rakan sedang bercakap di hadapan kelas, kita perlu:','Bercakap sendiri','Mendengar dengan hormat','Ketawa','Ganggu percakapan','B');
